import * as stylex from "@stylexjs/stylex";
import {
  createFileRoute,
  Link,
  redirect,
  useRouter,
} from "@tanstack/react-router";
import { Button } from "../components/ui/button";
import { Avatar, Icon } from "../components/ui/primitives";
import { getStartupAgent } from "../features/agents/startup-functions";
import { agentStyles } from "../features/agents/styles";
import { motion } from "../styles/motion.stylex";
import { colors } from "../styles/tokens.stylex";
import { Route as RootRoute } from "./__root";

export const Route = createFileRoute("/")({
  beforeLoad: async () => {
    // Only full page launches restore the last agent. Clicking Home still opens
    // the agent list; explicit links to settings or other agents stay intact.
    if (!import.meta.env.SSR) return;
    const agentId = await getStartupAgent();
    if (agentId)
      throw redirect({
        to: "/agents/$agentId",
        params: { agentId },
        replace: true,
        headers: { "Cache-Control": "private, no-store" },
      });
  },
  component: Home,
});

function Home() {
  const result = RootRoute.useLoaderData();
  const router = useRouter();

  return (
    <section {...stylex.props(agentStyles.page)}>
      <header {...stylex.props(styles.header)}>
        <h1 {...stylex.props(agentStyles.title)}>Your agents</h1>
        {result.ok && result.value.length > 0 && (
          <Link to="/agents/new" {...stylex.props(styles.create)}>
            <Icon name="plus" />
            Create agent
          </Link>
        )}
      </header>
      {!result.ok ? (
        <Button onClick={() => void router.invalidate()}>Try again</Button>
      ) : result.value.length === 0 ? (
        <div {...stylex.props(styles.empty)}>
          <p {...stylex.props(agentStyles.muted)}>
            Create your first agent to start a conversation.
          </p>
          <Link to="/agents/new" {...stylex.props(agentStyles.primary)}>
            Create an agent
          </Link>
        </div>
      ) : (
        <nav aria-label="Choose an agent" {...stylex.props(styles.list)}>
          {result.value.map((agent) => (
            <Link
              key={agent.id}
              to="/agents/$agentId"
              params={{ agentId: agent.id }}
              {...stylex.props(styles.agent)}
            >
              <Avatar character={agent.character} size={36} />
              <span {...stylex.props(styles.name)}>{agent.name}</span>
              <Icon name="chevron-right" />
            </Link>
          ))}
        </nav>
      )}
    </section>
  );
}

const styles = stylex.create({
  header: {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    flexWrap: "wrap",
    gap: 12,
    marginBottom: 16,
  },
  create: {
    display: "inline-flex",
    alignItems: "center",
    gap: 6,
    minHeight: 44,
    color: colors.accent,
    textDecoration: "none",
  },
  list: { display: "flex", flexDirection: "column" },
  agent: {
    display: "flex",
    alignItems: "center",
    gap: 14,
    paddingBlock: 16,
    paddingInline: 8,
    minHeight: 68,
    borderBottomWidth: 1,
    borderBottomStyle: "solid",
    borderBottomColor: colors.border,
    color: colors.foreground,
    textDecoration: "none",
    backgroundColor: {
      default: "transparent",
      "@media (hover: hover)": { ":hover": colors.bubble },
    },
    borderRadius: 6,
    outlineOffset: 2,
    transitionProperty: "background-color",
    transitionDuration: motion.fast,
    transitionTimingFunction: motion.easeOut,
  },
  name: { flex: 1, minWidth: 0, overflowWrap: "anywhere", fontSize: 16 },
  empty: {
    display: "flex",
    flexDirection: "column",
    alignItems: "flex-start",
    gap: 12,
  },
});

import { definePlugin } from "nitro";
import { closeAgentRuntimes } from "./codex/agent-runtime.server";
import { closeLogin } from "./codex/login.server";
import { startWorker } from "./runs/worker.server";

export default definePlugin((app) => {
  const stop = startWorker();
  app.hooks.hook("close", async () => {
    await stop();
    await closeLogin();
    await closeAgentRuntimes();
  });
});

import { mkdirSync } from "node:fs";
import { join, resolve } from "node:path";
import { DatabaseSync } from "node:sqlite";
import { Data, Effect, Schema } from "effect";
import { Agent, CreateAgentInput } from "../../features/agents/schema";

export class AgentStoreError extends Data.TaggedError("AgentStoreError")<{
  message: string;
}> {}

export function withAgentStore<A>(
  run: (db: DatabaseSync, directory: string) => A,
  directory = resolve(process.env.ROOST_DATA_DIR ?? ".roost"),
) {
  return Effect.try({
    try: () => {
      mkdirSync(directory, { recursive: true });
      const db = new DatabaseSync(join(directory, "roost.sqlite"));
      try {
        db.exec("PRAGMA busy_timeout = 5000");
        const version = Number(
          db.prepare("PRAGMA user_version").get()?.user_version,
        );
        if (version > 6)
          throw new AgentStoreError({
            message: "This database needs a newer version of Roost.",
          });
        if (version === 0) {
          db.exec("BEGIN IMMEDIATE");
          try {
            db.exec(`
          CREATE TABLE IF NOT EXISTS agents (
            id TEXT PRIMARY KEY, name TEXT NOT NULL, instructions TEXT NOT NULL,
            character TEXT NOT NULL, model TEXT NOT NULL, createdAt TEXT NOT NULL
          );
          CREATE TABLE IF NOT EXISTS conversation_instructions (
            threadId TEXT PRIMARY KEY, instructions TEXT NOT NULL
          );
          CREATE TABLE IF NOT EXISTS conversations (
            agentId TEXT PRIMARY KEY, threadId TEXT NOT NULL
          );
          CREATE TABLE IF NOT EXISTS agent_sessions (
            agentId TEXT PRIMARY KEY, threadId TEXT NOT NULL, archive TEXT NOT NULL
          );
          CREATE TABLE IF NOT EXISTS thread_context (threadId TEXT PRIMARY KEY, position INTEGER NOT NULL);
          CREATE TABLE IF NOT EXISTS agent_tool_versions (threadId TEXT PRIMARY KEY, version INTEGER NOT NULL);
          CREATE TABLE IF NOT EXISTS timeline (
            position INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE,
            agentId TEXT NOT NULL, message TEXT NOT NULL
          );
          CREATE TABLE IF NOT EXISTS timeline_imports (agentId TEXT PRIMARY KEY);
          CREATE TABLE IF NOT EXISTS soul_changes (
            id TEXT PRIMARY KEY, agentId TEXT NOT NULL, source TEXT NOT NULL,
            reason TEXT NOT NULL, before TEXT NOT NULL, after TEXT NOT NULL,
            beforeRevision TEXT NOT NULL, afterRevision TEXT NOT NULL, createdAt TEXT NOT NULL
          );
          CREATE TABLE IF NOT EXISTS automations (
            id TEXT PRIMARY KEY, agentId TEXT NOT NULL, name TEXT NOT NULL,
            prompt TEXT NOT NULL, schedule TEXT NOT NULL, notification TEXT NOT NULL,
            revision INTEGER NOT NULL, enabled INTEGER NOT NULL, nextRunAt INTEGER
          );
          CREATE TABLE IF NOT EXISTS runs (
            id TEXT PRIMARY KEY, agentId TEXT NOT NULL, kind TEXT NOT NULL,
            prompt TEXT NOT NULL, status TEXT NOT NULL, automationId TEXT,
            scheduledFor INTEGER, createdAt INTEGER NOT NULL, startedAt INTEGER,
            finishedAt INTEGER, messages TEXT NOT NULL DEFAULT '[]', error TEXT,
            threadId TEXT, soulRevision TEXT, owner TEXT, cancelRequested INTEGER NOT NULL DEFAULT 0,
            automationSnapshot TEXT,
            UNIQUE (automationId, scheduledFor)
          );
          CREATE UNIQUE INDEX IF NOT EXISTS one_agent_run ON runs(agentId) WHERE status = 'running';
          CREATE TABLE IF NOT EXISTS worker_lease (id INTEGER PRIMARY KEY, owner TEXT NOT NULL, heartbeat INTEGER NOT NULL);
          CREATE TABLE IF NOT EXISTS runtime_control (id INTEGER PRIMARY KEY, maintenance INTEGER NOT NULL DEFAULT 0);
          INSERT OR IGNORE INTO runtime_control (id,maintenance) VALUES (1,0);
          PRAGMA user_version = 1;
          `);
            db.exec("COMMIT");
          } catch (error) {
            db.exec("ROLLBACK");
            throw error;
          }
        }
        if (version < 2) {
          db.exec(`BEGIN IMMEDIATE;
            CREATE TABLE IF NOT EXISTS delegations (
              id TEXT PRIMARY KEY, sourceAgentId TEXT NOT NULL,
              sourceRunId TEXT NOT NULL, targetAgentId TEXT NOT NULL,
              task TEXT NOT NULL, resultRunId TEXT UNIQUE
            );
            CREATE INDEX IF NOT EXISTS delegations_source ON delegations(sourceAgentId);
            PRAGMA user_version = 2;
            COMMIT;`);
        }
        if (version < 3) {
          db.exec(`BEGIN IMMEDIATE;
            ALTER TABLE timeline ADD COLUMN revision INTEGER NOT NULL DEFAULT 0;
            CREATE TABLE timeline_revision (id INTEGER PRIMARY KEY, value INTEGER NOT NULL);
            INSERT INTO timeline_revision VALUES (1, 0);
            CREATE INDEX timeline_agent_position ON timeline(agentId, position);
            CREATE INDEX timeline_agent_revision ON timeline(agentId, revision);
            CREATE INDEX runs_active_agent ON runs(agentId, status) WHERE status IN ('running','queued');
            CREATE TRIGGER timeline_insert_revision AFTER INSERT ON timeline BEGIN
              UPDATE timeline_revision SET value=value+1 WHERE id=1;
              UPDATE timeline SET revision=(SELECT value FROM timeline_revision WHERE id=1) WHERE position=NEW.position;
            END;
            CREATE TRIGGER timeline_update_revision AFTER UPDATE OF message ON timeline WHEN OLD.message != NEW.message BEGIN
              UPDATE timeline_revision SET value=value+1 WHERE id=1;
              UPDATE timeline SET revision=(SELECT value FROM timeline_revision WHERE id=1) WHERE position=NEW.position;
            END;
            PRAGMA user_version = 3;
            COMMIT;`);
        }
        if (version < 4) {
          db.exec(`BEGIN IMMEDIATE;
            CREATE TABLE files (
              id TEXT PRIMARY KEY, agentId TEXT NOT NULL, runId TEXT,
              name TEXT NOT NULL, mimeType TEXT NOT NULL, size INTEGER NOT NULL,
              kind TEXT NOT NULL CHECK(kind IN ('attachment','artifact')), createdAt INTEGER NOT NULL
            );
            CREATE INDEX files_agent_run ON files(agentId,runId);
            CREATE TABLE approvals (
              id TEXT PRIMARY KEY, agentId TEXT NOT NULL, runId TEXT NOT NULL,
              threadId TEXT NOT NULL, requestKey TEXT NOT NULL, request TEXT NOT NULL,
              status TEXT NOT NULL DEFAULT 'pending', response TEXT,
              createdAt INTEGER NOT NULL, resolvedAt INTEGER,
              UNIQUE(runId,requestKey)
            );
            CREATE INDEX approvals_agent_status ON approvals(agentId,status);
            CREATE TABLE push_subscriptions (
              endpoint TEXT PRIMARY KEY, subscription TEXT NOT NULL, createdAt INTEGER NOT NULL
            );
            PRAGMA user_version = 4;
            COMMIT;`);
        }
        if (version < 5) {
          db.exec(`BEGIN IMMEDIATE;
            CREATE TABLE dashboard_settings (id INTEGER PRIMARY KEY CHECK(id=1), enabled INTEGER NOT NULL DEFAULT 0);
            INSERT INTO dashboard_settings(id,enabled) VALUES(1,0);
            CREATE TABLE dashboards (
              agentId TEXT NOT NULL, key TEXT NOT NULL, title TEXT NOT NULL,
              blocks TEXT NOT NULL, revision INTEGER NOT NULL, updatedAt INTEGER NOT NULL,
              PRIMARY KEY(agentId,key)
            );
            PRAGMA user_version = 5;
            COMMIT;`);
        }
        if (version < 6) {
          db.exec(`BEGIN IMMEDIATE;
            CREATE TABLE notification_settings (id INTEGER PRIMARY KEY CHECK(id=1), preferences TEXT NOT NULL);
            INSERT INTO notification_settings(id,preferences) VALUES(1,'{"enabled":true,"turnCompleted":true,"agentUpdates":true,"needsAttention":true}');
            CREATE TABLE agent_notifications (
              id TEXT PRIMARY KEY, agentId TEXT NOT NULL, runId TEXT NOT NULL,
              requestId TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL,
              createdAt INTEGER NOT NULL, UNIQUE(agentId,requestId)
            );
            ALTER TABLE runs ADD COLUMN hasAgentUpdate INTEGER NOT NULL DEFAULT 0;
            PRAGMA user_version = 6;
            COMMIT;`);
        }
        return run(db, directory);
      } finally {
        db.close();
      }
    },
    catch: (error) =>
      error instanceof AgentStoreError
        ? error
        : new AgentStoreError({
            message:
              "Could not access agent storage. Check the Roost data directory permissions.",
          }),
  });
}

export const listAgents = (directory?: string) =>
  withAgentStore(
    (db) =>
      Schema.decodeUnknownSync(Schema.Array(Agent))(
        db.prepare("SELECT * FROM agents ORDER BY createdAt, id").all(),
      ),
    directory,
  );

export const saveAgent = (input: CreateAgentInput, directory?: string) =>
  withAgentStore((db, root) => {
    const data = Schema.decodeUnknownSync(CreateAgentInput)(input);
    db.exec("BEGIN IMMEDIATE");
    try {
      const existing = db
        .prepare("SELECT * FROM agents WHERE id = ?")
        .get(data.id);
      if (existing) {
        const agent = Schema.decodeUnknownSync(Agent)(existing);
        if (
          agent.name !== data.name ||
          agent.instructions !== data.instructions ||
          agent.character !== data.character ||
          agent.model !== data.model
        ) {
          throw new AgentStoreError({
            message:
              "This creation request was already used. Reload the form to create another agent.",
          });
        }
        db.exec("COMMIT");

        return agent;
      }
      const agent = { ...data, createdAt: new Date().toISOString() };
      mkdirSync(join(root, "workspaces", agent.id), { recursive: true });
      db.prepare(
        "INSERT INTO agents (id, name, instructions, character, model, createdAt) VALUES (?, ?, ?, ?, ?, ?)",
      ).run(
        agent.id,
        agent.name,
        agent.instructions,
        agent.character,
        agent.model,
        agent.createdAt,
      );
      db.exec("COMMIT");

      return agent;
    } catch (error) {
      db.exec("ROLLBACK");
      throw error;
    }
  }, directory);

export const getAgentConversation = (id: string) =>
  withAgentStore((db, root) => {
    const agent = db.prepare("SELECT * FROM agents WHERE id = ?").get(id);
    if (!agent) throw new AgentStoreError({ message: "Agent not found." });
    const session = db
      .prepare(
        "SELECT s.threadId, s.archive, i.instructions FROM agent_sessions s LEFT JOIN conversation_instructions i ON i.threadId = s.threadId WHERE s.agentId = ?",
      )
      .get(id);
    const row = db
      .prepare("SELECT threadId FROM conversations WHERE agentId = ?")
      .get(id);

    return {
      agent: Schema.decodeUnknownSync(Agent)(agent),
      workspace: join(root, "workspaces", id),
      codexHome: join(root, "agents", id, "codex"),
      soulPath: join(root, "agents", id, "SOUL.md"),
      threadId: session ? String(session.threadId) : null,
      toolVersion: session
        ? Number(
            db
              .prepare(
                "SELECT version FROM agent_tool_versions WHERE threadId=?",
              )
              .get(String(session.threadId))?.version ?? 0,
          )
        : 0,
      legacyThreadId: !session && row ? String(row.threadId) : null,
      archive: session ? String(session.archive) : "[]",
      appliedInstructions:
        typeof session?.instructions === "string" ? session.instructions : null,
    };
  });

export const saveConversationThread = (
  agentId: string,
  threadId: string,
  archive = "[]",
) =>
  withAgentStore((db) => {
    db.prepare(
      "INSERT INTO agent_sessions (agentId, threadId, archive) VALUES (?, ?, ?) ON CONFLICT(agentId) DO UPDATE SET threadId=excluded.threadId,archive=excluded.archive",
    ).run(agentId, threadId, archive);
    db.prepare(
      "INSERT OR REPLACE INTO agent_tool_versions (threadId,version) VALUES (?,8)",
    ).run(threadId);
  });

export const saveConversationInstructions = (
  threadId: string,
  instructions: string,
) =>
  withAgentStore((db) => {
    db.prepare(
      "INSERT INTO conversation_instructions (threadId, instructions) VALUES (?, ?) ON CONFLICT(threadId) DO UPDATE SET instructions = excluded.instructions",
    ).run(threadId, instructions);
  });

import type { DatabaseSync } from "node:sqlite";
import { Schema } from "effect";
import {
  DashboardWidget,
  DeleteDashboard,
  SaveDashboard,
} from "../../features/dashboards/schema";
import { AgentStoreError, withAgentStore } from "../agents/store.server";
import { requireAgent } from "../automations/store.server";
import { assertAvailable } from "../maintenance.server";
import { writeTransaction } from "../transaction.server";

function enabled(db: DatabaseSync) {
  return (
    db.prepare("SELECT enabled FROM dashboard_settings WHERE id=1").get()
      ?.enabled === 1
  );
}

function requireEnabled(db: DatabaseSync) {
  assertAvailable(db);
  if (!enabled(db))
    throw new AgentStoreError({
      message: "Dashboards are off. The user can enable them in Settings.",
    });
}

export const getDashboardPreference = () =>
  withAgentStore((db) => ({ enabled: enabled(db) }));

export const setDashboardPreference = (value: boolean) =>
  withAgentStore((db) => {
    assertAvailable(db);
    db.prepare("UPDATE dashboard_settings SET enabled=? WHERE id=1").run(
      Number(value),
    );
    return { enabled: value };
  });

export const listDashboards = (agentId: string) =>
  withAgentStore((db) => {
    requireEnabled(db);
    requireAgent(db, agentId);
    const rows = db
      .prepare(
        "SELECT * FROM dashboards WHERE agentId=? ORDER BY updatedAt DESC,key",
      )
      .all(agentId);
    return rows.map((row) =>
      Schema.decodeUnknownSync(DashboardWidget)({
        ...row,
        blocks: JSON.parse(String(row.blocks)),
      }),
    );
  });

export const saveDashboard = (agentId: string, input: SaveDashboard) =>
  withAgentStore((db) =>
    writeTransaction(db, () => {
      requireEnabled(db);
      requireAgent(db, agentId);
      const data = Schema.decodeUnknownSync(SaveDashboard)(input);
      const existing = db
        .prepare("SELECT revision FROM dashboards WHERE agentId=? AND key=?")
        .get(agentId, data.key);
      if (
        existing
          ? existing.revision !== data.expectedRevision
          : data.expectedRevision !== undefined
      )
        throw new AgentStoreError({
          message: "This dashboard changed. Read it again before saving.",
        });
      if (
        !existing &&
        Number(
          db
            .prepare("SELECT COUNT(*) AS count FROM dashboards WHERE agentId=?")
            .get(agentId)!.count,
        ) >= 30
      )
        throw new AgentStoreError({
          message:
            "Each agent can keep up to 30 dashboard widgets. Update or remove an existing widget first.",
        });
      const widget: DashboardWidget = {
        agentId,
        key: data.key,
        title: data.title,
        blocks: data.blocks,
        revision: existing ? Number(existing.revision) + 1 : 1,
        updatedAt: Date.now(),
      };
      db.prepare(
        "INSERT INTO dashboards (agentId,key,title,blocks,revision,updatedAt) VALUES (?,?,?,?,?,?) ON CONFLICT(agentId,key) DO UPDATE SET title=excluded.title,blocks=excluded.blocks,revision=excluded.revision,updatedAt=excluded.updatedAt",
      ).run(
        agentId,
        widget.key,
        widget.title,
        JSON.stringify(widget.blocks),
        widget.revision,
        widget.updatedAt,
      );
      return widget;
    }),
  );

export const deleteDashboard = (agentId: string, input: DeleteDashboard) =>
  withAgentStore((db) => {
    requireEnabled(db);
    requireAgent(db, agentId);
    const data = Schema.decodeUnknownSync(DeleteDashboard)(input);
    const result = db
      .prepare(
        "DELETE FROM dashboards WHERE agentId=? AND key=? AND revision=?",
      )
      .run(agentId, data.key, data.expectedRevision);
    if (!result.changes)
      throw new AgentStoreError({
        message: "This dashboard changed. Read it again before removing it.",
      });
    return { removed: true };
  });

import { withAgentStore } from "../agents/store.server";
import { requireAgent } from "../automations/store.server";
import { assertAvailable } from "../maintenance.server";
import { readTimelinePage } from "./timeline.server";

// Read only Roost's saved state. SSR must not start a worker, import a legacy
// Codex thread, or contact a provider before it can show the conversation.
export const readConversationSnapshot = (
  agentId: string,
  options: { since?: number; before?: number } = {},
  directory?: string,
) =>
  withAgentStore((db) => {
    assertAvailable(db);
    requireAgent(db, agentId);
    const page = readTimelinePage(db, agentId, options);
    const run = db
      .prepare(
        "SELECT id FROM runs WHERE agentId=? AND status IN ('running','queued') ORDER BY CASE status WHEN 'running' THEN 0 ELSE 1 END,createdAt LIMIT 1",
      )
      .get(agentId);
    const computer = run
      ? db
          .prepare(
            "SELECT id FROM timeline WHERE agentId=? AND position>(SELECT position FROM timeline WHERE agentId=? AND id=?) AND json_extract(message,'$.title')='roost_computer' ORDER BY position DESC LIMIT 1",
          )
          .get(agentId, agentId, String(run.id))
      : undefined;
    const needsImport =
      !db
        .prepare("SELECT agentId FROM timeline_imports WHERE agentId=?")
        .get(agentId) &&
      !!db
        .prepare(
          "SELECT agentId FROM agent_sessions WHERE agentId=? UNION ALL SELECT agentId FROM conversations WHERE agentId=? LIMIT 1",
        )
        .get(agentId, agentId);

    return {
      ...page,
      busy: !!run,
      runId: run ? String(run.id) : null,
      computerAnchor: computer ? String(computer.id) : null,
      needsImport,
    };
  }, directory);

import { createFileRoute } from "@tanstack/react-router";
import { Conversation } from "../components/conversation";
import { getConversationSnapshot } from "../features/chat/functions";
import { Route as RootRoute } from "./__root";

export const Route = createFileRoute("/agents/$agentId")({
  head: ({ params }) => ({
    scripts: [
      {
        // An internally resolved PWA launch must have its canonical URL before
        // hydration. Direct links and in-app Home navigation stay untouched.
        children: `if(location.pathname==="/"&&!location.search)history.replaceState(history.state,"",${JSON.stringify(`/agents/${encodeURIComponent(params.agentId)}`)}+location.hash);`,
      },
    ],
  }),
  loader: ({ params }) =>
    getConversationSnapshot({ data: { agentId: params.agentId } }).catch(
      () => ({
        ok: false as const,
        error: "Could not access this conversation. Check Roost and retry.",
      }),
    ),
  headers: () => ({ "Cache-Control": "private, no-store" }),
  component: AgentPage,
});

function AgentPage() {
  const { agentId } = Route.useParams();
  const initialConversation = Route.useLoaderData();
  const result = RootRoute.useLoaderData();
  const agent = result.ok
    ? result.value.find((agent) => agent.id === agentId)
    : undefined;
  if (!agent) return <p>Agent not found.</p>;
  return (
    <Conversation
      key={agentId}
      agent={agent}
      initialConversation={initialConversation}
    />
  );
}

import { Schema } from "effect";
import { MAX_ATTACHMENTS } from "./files";

const FileAttachment = Schema.Struct({
  id: Schema.UUID,
  name: Schema.String,
  mimeType: Schema.String,
  size: Schema.NonNegativeInt,
  kind: Schema.Literal("attachment", "artifact"),
  url: Schema.String,
});

export const SendMessage = Schema.Struct({
  agentId: Schema.UUID,
  messageId: Schema.UUID,
  text: Schema.Trim.pipe(Schema.maxLength(32000)),
  attachmentIds: Schema.optional(
    Schema.Array(Schema.UUID).pipe(Schema.maxItems(MAX_ATTACHMENTS)),
  ),
});

export type SendMessage = typeof SendMessage.Type;

export const Message = Schema.Struct({
  id: Schema.String,
  role: Schema.Literal("user", "assistant", "notice", "activity"),
  text: Schema.String,
  files: Schema.optional(Schema.Array(FileAttachment)),
  title: Schema.optional(Schema.String),
  status: Schema.optional(Schema.String),
  details: Schema.optional(Schema.String),
  truncated: Schema.optional(Schema.Boolean),
  referenceId: Schema.optional(Schema.String),
  noticeKind: Schema.optional(
    Schema.Literal("soul", "automation", "run", "delegation", "approval"),
  ),
});

export type Message = typeof Message.Type;

export const ChatEvent = Schema.Union(
  Schema.Struct({
    type: Schema.Literal("history"),
    messages: Schema.Array(Message),
  }),
  Schema.Struct({
    type: Schema.Literal("delta"),
    id: Schema.String,
    text: Schema.String,
  }),
  Schema.Struct({ type: Schema.Literal("message"), message: Message }),
  Schema.Struct({
    type: Schema.Literal("activityDelta"),
    id: Schema.String,
    title: Schema.String,
    text: Schema.String,
  }),
  Schema.Struct({ type: Schema.Literal("done"), status: Schema.String }),
  Schema.Struct({ type: Schema.Literal("error"), message: Schema.String }),
);

export type ChatEvent = typeof ChatEvent.Type;

import { Schema } from "effect";

const label = Schema.Trim.pipe(Schema.minLength(1), Schema.maxLength(100));
const text = Schema.String.pipe(Schema.maxLength(2000));
const url = Schema.String.pipe(
  Schema.maxLength(2000),
  Schema.filter(
    (value) => {
      try {
        return ["https:", "http:"].includes(new URL(value).protocol);
      } catch {
        return false;
      }
    },
    { message: () => "Use an http or https source URL." },
  ),
);

export const DashboardBlock = Schema.Union(
  Schema.Struct({
    type: Schema.Literal("markdown"),
    text: Schema.String.pipe(Schema.maxLength(12000)),
  }),
  Schema.Struct({
    type: Schema.Literal("metrics"),
    items: Schema.Array(
      Schema.Struct({ label, value: label, note: Schema.optional(text) }),
    ).pipe(Schema.minItems(1), Schema.maxItems(8)),
  }),
  Schema.Struct({
    type: Schema.Literal("table"),
    columns: Schema.Array(label).pipe(Schema.minItems(1), Schema.maxItems(8)),
    rows: Schema.Array(Schema.Array(text).pipe(Schema.maxItems(8))).pipe(
      Schema.maxItems(50),
    ),
  }).pipe(
    Schema.filter(
      (block) => block.rows.every((row) => row.length === block.columns.length),
      { message: () => "Every table row must have one cell per column." },
    ),
  ),
  Schema.Struct({
    type: Schema.Literal("chart"),
    title: label,
    style: Schema.Literal("line", "bar"),
    points: Schema.Array(
      Schema.Struct({
        label,
