import {readFileSync, existsSync, statSync} from 'node:fs';
const readme = readFileSync('README.md','utf8');
const refs = [...readme.matchAll(/\]\(([^)]+)\)|src="([^"]+)"/g)].map(m=>m[1]??m[2]);
let count = 0;
for (const ref of refs) {
  if (/^(https?:|#)/.test(ref)) continue;
  if (!existsSync(ref.split('#')[0])) throw new Error(`Missing README target: ${ref}`);
  count++;
}
let bytes = 0;
for (const name of ['conversation','dashboard','automations','mobile']) {
  const path = `docs/screenshots/${name}.png`;
  const data = readFileSync(path);
  if(data.subarray(0,8).toString('hex') !== '89504e470d0a1a0a') throw new Error(`Invalid PNG: ${path}`);
  console.log(`${path}: ${data.readUInt32BE(16)} × ${data.readUInt32BE(20)}`);
  bytes += statSync(path).size;
}
console.log(`Checked ${count} local README links/images; screenshots total ${(bytes/1024).toFixed(0)} KiB.`);
